func (s *Store) UpdateWaveAndStage(ctx context.Context, id int64, waveNum int, stage, assignedModel string, priorityScore float64) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	_, err := s.db.ExecContext(ctx,
		`UPDATE task_queue SET wave_num = ?, stage = ?, assigned_model = ?, priority_score = ?, updated_at = ? WHERE id = ?`,
		waveNum, stage, assignedModel, priorityScore, time.Now().Unix(), id,
	)
	return err
}

